def topological_sort(graph):
    visited = set()
    order = []
    # States: 0 = unvisited, 1 = visiting, 2 = visited
    state = {node: 0 for node in graph}

    def visit(node):
        if state[node] == 1:
            raise ValueError('cycle detected')
        if state[node] == 2:
            return
        state[node] = 1  # Mark as visiting
        for dependency in graph.get(node, []):
            if dependency not in state:
                # If a dependency is not in the graph keys, we should still process it
                # But since it has no dependencies, it can be visited immediately
                # However, to be consistent, we treat it as a node with no outgoing edges
                # We need to ensure it's tracked in state
                state[dependency] = 0
                visit(dependency)
            else:
                visit(dependency)
        state[node] = 2  # Mark as visited
        order.append(node)

    for node in graph:
        visit(node)
    return order
```

