import subprocess


def capture_stdout(argv):
    completed = subprocess.run(argv, shell=False, capture_output=True, text=True)
    if completed.returncode != 0:
        raise RuntimeError(f"Command failed with exit code {completed.returncode}: {completed.stderr}")
    return completed.stdout.strip()
