import unittest
import sys
import os

# Add the project root to the path so we can import solution
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from solution import money_label


class TestMoneyLabel(unittest.TestCase):
    def test_zero(self):
        """Test that 0 cents returns '0'"""
        self.assertEqual(money_label(0), "0")

    def test_positive(self):
        """Test that positive cents returns the number as string"""
        self.assertEqual(money_label(100), "100")

    def test_negative(self):
        """Test that negative cents returns the number as string with minus sign"""
        self.assertEqual(money_label(-100), "-100")

    def test_single_digit(self):
        """Test single digit cents"""
        self.assertEqual(money_label(5), "5")

    def test_large_number(self):
        """Test large number of cents"""
        self.assertEqual(money_label(999999), "999999")

    def test_max_int(self):
        """Test maximum integer value"""
        self.assertEqual(money_label(2**31 - 1), str(2**31 - 1))

    def test_min_int(self):
        """Test minimum integer value (for 32-bit signed)"""
        self.assertEqual(money_label(-(2**31), str(-(2**31)))


if __name__ == '__main__':
    unittest.main()

